content.css:
#landing-page-wrapper-id {
  display: none;
}
/* ------------------------------Alert --------------------------------------------------- */
.d2VDT-alert-container {
  position: fixed;
  font-family: Arial, Helvetica, sans-serif;
  font-size: 14px;
  z-index: 20;
}
.valq-license-info.planning {
  top: 38% !important;
  left: 40% !important;
  bottom: auto;
}
.valq-license-info.center {
  top: 40% !important;
  left: 40% !important;
  bottom: auto;
}
.valq-license-overlay {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
}
.valq-license-info {
  position: fixed;
  bottom: 5px;
  right: 5px;
  width: 316px;
  height: auto;
  background: #ffffff 0% 0% no-repeat padding-box;
  box-shadow: 0px 0px 6px #00000033;
  opacity: 1;
  z-index: 13;
  /* .d2VDTPopUpBg z-index:  is set to 12!important hence 13 */
  box-sizing: content-box;
}
.valq-license-info-container {
  font-family: 'Segoe UI', wf_segoe-ui_normal, helvetica, arial, sans-serif !important;
  font-size: 14px;
  width: 276px;
  height: auto;
  display: flex;
  padding: 10px 20px;
  flex-direction: column;
  justify-content: space-around;
}
.valq-license-info-header {
  height: 27px;
  display: flex;
  font-size: 14px;
  color: #595a5c;
}
.valq-license-info-lock {
  margin: auto 5px auto 0px;
  height: 15px;
  width: 15px;
}
.valq-license-info-lock img {
  height: 15px !important;
  width: 15px !important;
}
.valq-license-info-header-text {
  display: flex;
  align-items: center;
}
.valq-license-info-message {
  height: auto;
  letter-spacing: 0;
  color: #595a5c;
}
.valq-license-info-button {
  height: 27px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: 600;
  margin-top: 10px;
}
.valq-license-info-login {
  background-color: #f2c811;
  border: 1px solid #f2c811;
}
.valq-license-info-upgrade {
  border: 1px solid #000000;
}
.valq-license-info-button:hover {
  border-color: #000;
  color: #000;
  cursor: pointer;
}
.valq-license-info-close {
  position: absolute;
  right: 15px;
  top: 10px;
  color: #555555b3;
  cursor: pointer;
}
@keyframes bottom-right {
  0% {
    right: -250px;
    bottom: 20px;
  }
  100% {
    right: 20px;
    bottom: 20px;
  }
}
@keyframes bottom-left {
  0% {
    left: -250px;
    bottom: 20px;
  }
  100% {
    left: 20px;
    bottom: 20px;
  }
}
@keyframes top-left {
  0% {
    left: -250px;
    top: 20px;
  }
  100% {
    left: 20px;
    top: 20px;
  }
}
@keyframes top-right {
  0% {
    right: -250px;
    top: 20px;
  }
  100% {
    right: 20px;
    top: 20px;
  }
}
.alert-box {
  display: flex;
  width: 325px;
  height: 60px;
  background-position: 15px center;
  box-shadow: -6px 6px 0.5rem rgba(33, 33, 33, 0.3);
  background-repeat: no-repeat;
  color: white;
  font-size: 13px;
}
.alert-msg {
  display: flex;
  padding: 10px;
  width: auto;
  opacity: 1;
  min-width: 100px;
}
.alert-box.loading {
  background-color: black;
}
.alert-box.success {
  background-color: #43a047;
}
.alert-box.error {
  background-color: #d32f2f;
}
.alert-box.warning {
  background-color: #fff4ce;
  color: black;
}
.alert-icon {
  font-size: 16px;
  padding: 10px;
  padding-bottom: 0px;
  padding-right: 0px;
}
.alert-icon.warning::before {
  content: '\f147';
  font-family: 'VDT-icons';
}
.alert-icon.loading::before {
  content: '\f148';
  font-family: 'VDT-icons';
}
.alert-icon.success::before {
  content: '\f146';
  font-family: 'VDT-icons';
}
.alert-icon.error::before {
  content: '\f147';
  font-family: 'VDT-icons';
}
.d2VDT-alert-container.transition {
  -webkit-animation-duration: 0.5s;
  animation-duration: 0.5s;
}
.d2VDT-alert-container.top-right {
  -webkit-animation-name: top-right;
  animation-name: top-right;
  top: 20px;
  right: 20px;
}
.d2VDT-alert-container.top-left {
  -webkit-animation-name: top-left;
  animation-name: top-left;
  top: 20px;
  left: 20px;
}
.d2VDT-alert-container.bottom-left {
  -webkit-animation-name: bottom-left;
  animation-name: bottom-left;
  bottom: 20px;
  left: 20px;
}
.d2VDT-alert-container.bottom-right {
  -webkit-animation-name: bottom-right;
  animation-name: bottom-right;
  bottom: 20px;
  right: 20px;
}
.alert-close {
  height: 24px;
  width: 24px;
  padding: 2px;
  border: inherit;
  z-index: 112;
  right: 0;
  top: 0;
  opacity: 0.7;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: 0.2s all;
}
.alert-close:hover {
  opacity: 1;
  background-color: #f4f4f4;
  cursor: pointer;
}
.alert-close img {
  height: 12px;
  width: 12px;
}
.valq-free-plan-popup {
  position: fixed;
  bottom: 5px;
  right: 5px;
  width: 316px;
  height: auto;
  background: #ffffff 0% 0% no-repeat padding-box;
  box-shadow: 0px 0px 6px #00000033;
  opacity: 1;
  z-index: 9999;
  box-sizing: content-box;
  display: flex;
  flex-direction: column;
  padding: 40px;
}
.valq-free-plan-popup.small {
  padding: 10px;
  width: 270px;
}
.valq-free-plan-popup.small .free-plan-header {
  display: none !important;
}
.valq-free-plan-popup.small .free-plan-upgrade-btn {
  margin-top: 0px !important;
  margin-bottom: 0px !important;
}
.valq-free-plan-popup.top {
  position: absolute;
  top: 40px;
  bottom: unset;
  width: 316px;
}
.valq-free-plan-popup.top.model {
  top: 75px;
}
.valq-free-plan-popup .logo-div {
  width: 91px;
  height: 40px;
  padding-bottom: 5px;
}
.application-logo {
  width: 100% !important;
  height: 40px !important;
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  background-image: url(data:image/png;base64,);
}
.valq-free-plan-popup .logo-div .application-logo {
  width: 100%;
  height: 100%;
  background-repeat: no-repeat;
  background-size: cover;
}
.valq-free-plan-popup .free-plan-header {
  font-size: 15px;
  font-weight: 400;
  margin-bottom: 5px;
}
.valq-free-plan-popup .free-plan-header {
  font-size: 24px;
  font-weight: 400;
  margin-bottom: 10px;
}
.valq-free-plan-popup .free-plan-description {
  font-size: 14px;
  padding: 7px 0px;
}
.valq-free-plan-popup .free-plan-upgrade-btn {
  width: 183px;
  font-size: 14px;
  margin-top: 20px;
  margin-bottom: 20px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: 600;
  font-size: 12px;
  background-color: #f3c412;
  border: 1px solid #f3c412;
  cursor: pointer;
  padding: 5px;
}
.valq-free-plan-popup .help-container {
  display: flex;
  flex-direction: column;
}
.valq-free-plan-popup .help-container span {
  color: #0078d4;
  font-size: 14px;
  cursor: pointer;
}
.help-modal {
  z-index: 112;
  background-color: #ffffff;
  font-family: 'Segoe UI', wf_segoe-ui_normal, helvetica, arial, sans-serif;
  box-shadow: 0 0 20px #bbb;
  position: absolute;
  bottom: 32px;
  padding: 10px;
  color: #444444;
}
.help-modal .close-modal {
  position: absolute;
  right: 10px;
  top: 10px;
  cursor: pointer;
  font-size: 10px;
}
.help-modal .close-modal:before {
  content: '\E8BB';
  font-family: 'FabricMDL2Icons';
  color: #333333;
}
.help-modal h3 {
  font-size: 18px;
  font-weight: 400 !important;
  padding-left: 8px;
  margin: 0;
}
.section {
  display: flex;
  flex-direction: column;
  margin: 12px 0 2px 0;
}
.section p {
  text-transform: uppercase !important;
  font-weight: 500 !important;
}
.section .section-label {
  font-size: 12px;
  line-height: 14px;
}
.help-link {
  display: block;
  font-size: 12px;
  text-decoration: none;
  box-shadow: none !important;
  color: #0078d4;
  line-height: 16px;
  margin-bottom: 10px;
}
.build-details {
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  border-bottom: 1px solid #ddd;
  padding-bottom: 10px;
}
.build-details > p {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  margin: 0 12px 0 0;
}
.licensed-to {
  font-weight: 600 !important;
  font-size: 13px;
}
.plan-detail {
  display: flex;
}
.plan-name {
  font-weight: 400;
  font-size: 12px;
  margin: 0px;
}
.sub-detail {
  font-size: 9px;
  font-family: 'Inforiver Sans';
  color: darkgray;
  font-weight: 100;
  margin: 0px;
  padding: 5px 0px 0px 4px;
  user-select: all;
}
.expiry-detail {
  font-weight: 100;
  font-size: 10px !important;
}
.footer {
  display: flex;
  flex-direction: row;
  align-items: center;
  border-top: 1px solid #ddd;
  padding-top: 10px;
}
.footer .help-modal-logo {
  height: 25px;
  width: 25px;
  background-size: cover;
  margin-right: 4px;
}
.footer p {
  margin: 0;
  font-size: 12px;
  font-weight: normal;
}
.inforiver-config-popup {
  display: flex;
  align-items: center;
  justify-content: center;
  position: fixed;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: rgba(0, 0, 0, 0.25);
  z-index: 2;
}
.inforiver-config-popup .valq-free-plan-popup {
  position: unset;
  top: unset;
  padding: 25px;
}
.inforiver-config-popup .valq-free-plan-popup .inforiver-config-popup-header {
  display: flex;
  flex-direction: row;
  align-items: center;
  margin-bottom: 10px;
}
.inforiver-config-popup .valq-free-plan-popup .inforiver-config-popup-header .free-plan-header {
  font-size: 18px;
  margin-left: 6px;
  margin-bottom: unset;
}
.inforiver-config-popup .valq-free-plan-popup .free-plan-description {
  font-weight: 400;
  font-size: 12px;
  color: #000;
}
.inforiver-config-popup .valq-free-plan-popup .valq-license-info-sign-in {
  display: flex;
  justify-content: center;
  padding: 5px;
  background: #0078d4;
  color: #fff;
  margin-top: 10px;
  cursor: pointer;
  font-size: 12px;
}
.warning-wrapper {
  position: fixed;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background-color: #fff;
  padding: 20px;
  box-shadow: 0px 6px 8px #80808d;
  max-width: 532px;
  z-index: 100;
}
.warning-wrapper .content-wrapper {
  display: flex;
  flex-direction: column;
}
.warning-wrapper .button-wrapper {
  margin-top: 20px;
  display: flex;
  justify-content: flex-end;
}
.warning-wrapper .title {
  font-size: 16px;
  margin-bottom: 10px;
}
.warning-wrapper .paragraph {
  color: #000;
  padding: 6px 0;
  font-size: 14px;
}
.warning-wrapper .button {
  font-size: 12px;
  color: #0078d4;
  border: 1px solid #0078d4;
  font-weight: 600;
  background: transparent;
  padding: 10px;
  border-radius: 2px;
  cursor: pointer;
}
.warning-wrapper .processing-text {
  display: flex;
  margin-top: 10px;
  font-size: 12px;
  color: #000;
  justify-content: flex-end;
}

/* 
  Input.scss 
  - Includes all default styles for the Input component
*/
.form-input {
  box-shadow: none;
  background: none transparent;
  margin: 0;
  padding: 0 0.6rem;
  box-sizing: border-box;
  background-image: initial;
  border: 0.05rem solid #a6a6a6;
  border-radius: 0;
  color: #333333;
  display: block;
  font-size: 13px;
  text-overflow: ellipsis;
  outline: 0px;
  height: 1.8rem;
  line-height: 1.2rem;
  max-width: 100%;
  position: relative;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
  width: 100%;
  margin-top: 6px;
}
.form-input:hover {
  border-color: #333333;
}
.form-input:focus {
  border-color: #0078d4;
}
.form-input::placeholder {
  color: #a6a6a6;
  font-size: 13px;
}
.form-input.input-inline {
  display: inline-block;
  vertical-align: middle;
  width: auto;
}
.form-input[type=file] {
  height: auto;
}
.has-icon-left,
.has-icon-right {
  position: relative;
}
.has-icon-left .form-icon,
.has-icon-right .form-icon {
  height: 0.8rem;
  margin: 0 0.25rem;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 0.8rem;
  z-index: 2;
}
.has-icon-left .form-icon {
  left: 0.05rem;
}
.has-icon-left .form-input {
  padding-left: 1.3rem;
}
.has-icon-right .form-icon {
  right: 0.05rem;
}
.has-icon-right .form-input {
  padding-right: 1.3rem;
}
.has-success .form-input,
.form-input.is-success {
  background: #fdfef2;
  border-color: #bad80a;
}
.has-success .form-input:focus,
.form-input.is-success:focus {
  box-shadow: 0 0 0 0.1rem rgba(186, 216, 10, 0.2);
}
.has-error .form-input,
.form-input.is-error {
  background: white;
  border-color: #e81123;
  color: #e81123;
}
.has-error .form-input:focus,
.form-input.is-error:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
}
.form-input:not(:placeholder-shown):invalid {
  border-color: #e81123;
  color: #e81123;
}
.form-input:not(:placeholder-shown):invalid:focus {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  background: white;
}
.form-input:not(:placeholder-shown):invalid + .form-input-hint {
  color: #e81123;
}
.form-input:disabled,
.form-input.disabled,
.bf-ui-form-select:disabled,
.bf-ui-form-select.disabled {
  background-color: #f7f7f7;
  cursor: not-allowed;
  opacity: 0.5;
}
.form-input[readonly] {
  background-color: #ffffff;
}
textarea.form-input,
textarea.form-input.input-lg,
textarea.form-input.input-sm {
  padding: 0 0.6rem;
  height: auto;
}

/* 
  Switch.scss 
  - Includes all default styles for the Switch component
*/
.form-switch {
  font-size: 0.6rem;
  display: block;
  line-height: 1.2rem;
  margin: 0.2rem 0;
  min-height: 1.2rem;
  padding: 0.1rem 0.4rem 0.1rem 1.2rem;
  position: relative;
}
.form-switch input {
  clip: rect(0, 0, 0, 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.form-switch input:focus + .form-icon {
  border-color: #a6a6a6;
}
.form-switch input:checked + .form-icon {
  background: #f4f4f4;
  border-color: #0078d4;
  box-shadow: none;
}
.form-switch .form-icon {
  border: 0.05rem solid #adadad;
  cursor: pointer;
  display: inline-block;
  position: absolute;
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s;
}
.form-switch span {
  padding-left: 0.8rem;
}
.form-switch .form-icon {
  background: #f4f4f4;
  background-clip: padding-box;
  border-radius: 0.45rem;
  height: 0.9rem;
  left: 0;
  width: 1.6rem;
  border-color: #333333;
  top: 0.25rem;
}
.form-switch .form-icon::before {
  background: #333333;
  border-radius: 50%;
  content: "";
  display: block;
  height: 0.6rem;
  left: 3px;
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  transition: background 0.2s, border 0.2s, box-shadow 0.2s, color 0.2s, left 0.2s;
  width: 0.6rem;
}
.form-switch input:checked + .form-icon {
  background-color: #0078d4;
  border: none;
}
.form-switch input:checked + .form-icon::before {
  background-color: #f4f4f4;
  left: 16px;
}
.form-switch input:active + .form-icon::before {
  background-color: #0078d4;
}
.has-error .form-switch .form-icon,
.form-switch.is-error .form-icon {
  border-color: #e81123;
}
.has-error .form-switch .form-icon::before,
.form-switch.is-error .form-icon::before {
  background-color: #e81123;
}
.has-error .form-switch input:checked + .form-icon,
.form-switch.is-error input:checked + .form-icon {
  background: #e81123;
  border-color: #e81123;
}
.has-error .form-switch input:focus + .form-icon,
.form-switch.is-error input:focus + .form-icon {
  box-shadow: 0 0 0 0.1rem rgba(232, 17, 35, 0.2);
  border-color: #e81123;
}
.form-switch input:disabled + .form-icon,
.form-switch input.disabled + .form-icon {
  opacity: 0.5;
}
.form-switch input:checked:disabled + .form-icon,
.form-switch input:checked.disabled + .form-icon {
  opacity: 0.5;
}
.form-switch.mini .form-icon {
  height: 0.1rem;
  width: 1.3rem;
  top: 0.5rem;
}
.form-switch.mini .form-icon::before {
  height: 0.6rem;
  width: 0.6rem;
  left: -1px;
  background-color: #FFF;
  border: 2px #333 solid;
}
.form-switch.mini input:active + .form-icon::before {
  background-color: #333;
}
.form-switch.mini input:focus + .form-icon {
  border-color: #333;
}
.form-switch.mini input:checked + .form-icon::before {
  left: 14px;
  background-color: #0078d4;
  border: none;
}
.form-switch.mini.has-error .form-switch.mini .form-icon::before,
.form-switch.mini.is-error .form-icon::before {
  border-color: #e81123;
}
.form-switch.mini.has-error .form-switch.mini input:checked + .form-icon::before,
.form-switch.mini.is-error input:checked + .form-icon::before {
  background: #e81123;
}

.DatePicker {
  position: relative;
  display: inline-block;
  z-index: 100;
}
.DatePicker__input {
  background: #fff;
  border: 1px solid #ddd;
  padding: 0.4em 0.8em;
  font-family: inherit;
  text-align: center;
  font-size: 12px;
}
.DatePicker__input.-rtl {
  direction: rtl;
}
.DatePicker__input::placeholder {
  color: #979797;
}
.DatePicker__calendarContainer.-top + .DatePicker__calendarArrow {
  top: auto;
  bottom: calc(100% + 10px);
  transform: translateY(-2.5rem) rotate(180deg);
  animation: fadeArrowFlipped 0.3s forwards;
}
.DatePicker__calendarContainer {
  position: absolute;
  top: calc(100% + 20px);
  left: 50%;
  transform: translateX(-50%);
}
.DatePicker__calendarContainer.-top {
  top: auto;
  bottom: calc(100% + 20px);
}
.Calendar,
.Calendar * {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  direction: ltr;
}
.Calendar,
.Calendar.-rtl * {
  direction: rtl;
}
.DatePicker__calendarArrow {
  position: absolute;
  width: 0;
  height: 0;
  top: calc(100% + 10px);
  left: 0;
  right: 0;
  margin: 0 auto;
  border-style: solid;
  z-index: 10;
  border-width: 0 10px 10px 10px;
  border-color: transparent transparent #fff transparent;
}
.Calendar {
  --cl-color-black: #444444;
  --cl-color-disabled: #d4d4d4;
  --cl-color-error: #ff2929;
  font-size: 10px;
  background: #fff;
  box-shadow: 0 1em 4em rgba(0, 0, 0, 0.07);
  border-radius: 1em;
  position: relative;
  user-select: none;
  padding-top: 1.2em;
  display: flex;
  flex-direction: column;
  width: 33em;
  z-index: 10;
  max-width: 90vw;
  min-height: 36.7em;
}
.DatePicker .Calendar,
.DatePicker__calendarArrow {
  transform: translateY(2.5em);
  opacity: 0;
  animation: fadeCalendar 0.3s forwards;
}
.DatePicker__calendarContainer.-top .Calendar {
  transform: translateY(-2.5em);
}
.Calendar.-noFocusOutline *:focus {
  outline: none !important;
}
.Calendar > :not(.Calendar__footer) button {
  font-family: inherit;
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  outline: none;
}
.Calendar__header {
  display: flex;
  color: var(--cl-color-black);
  padding: 2em 2.9em;
  align-items: center;
  overflow: hidden;
}
.Calendar__monthArrowWrapper {
