.dropdown-root {
  position: relative;
  border: 1px solid #ccc;
}
.dropdown-placeholder {
  padding-left: 10px;
  padding-right: 20px;
  text-overflow: ellipsis;
  display: block;
  overflow: hidden;
  white-space: nowrap;
}
.dropdown-placeholder.is-placeholder {
  color: #A6A6A6;
  font-weight: 400;
}
.dropdown-control {
  position: relative;
  overflow: hidden;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: white;
  border: 0px solid #ccc;
  border-radius: 2px;
  box-sizing: border-box;
  cursor: default;
  outline: none;
  transition: all 200ms ease;
  font-size: 12px;
  font-weight: 600;
  color: #333;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif;
  cursor: pointer;
  height: 32px;
}
.dropdown-control:hover {
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.06);
}
.dropdown-control.dropdown-disabled {
  color: #ccc !important;
}
.dropdown-arrow-wrapper {
  border: solid #333;
  border-width: 0 1.5px 1.5px 0;
  padding: 3.5px;
  content: " ";
  display: block;
  height: 0;
  margin-top: -2px;
  position: absolute;
  right: 10px;
  top: 12px;
  width: 0;
  transform: rotate(45deg);
  -webkit-transform: rotate(45deg);
}
.dropdown-menu {
  display: flex;
  flex-direction: column;
  background-color: white;
  border: 1px solid rgba(0, 0, 0, 0.16);
  box-sizing: border-box;
  margin-top: 0.5px;
  max-height: 200px;
  overflow-y: auto;
  position: absolute;
  top: 100%;
  width: 100%;
  z-index: 99999;
  -webkit-overflow-scrolling: touch;
  font-size: 12px;
  box-shadow: -4px 4px 16px -2px rgba(33, 33, 33, 0.3);
}
.dropdown-menu .dropdown-group > .dropdown-title {
  padding: 8px 10px;
  color: #333333;
  font-weight: bold;
  text-transform: capitalize;
}
.dropdown-option {
  padding: 5px 10px;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
}
.dropdown-option span {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  box-sizing: border-box;
  color: rgba(51, 51, 51, 0.8);
  display: block;
  font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif !important;
}
.dropdown-option .right-placeholder {
  color: #c8c8c8;
}
.dropdown-option:last-child {
  border-bottom-right-radius: 2px;
  border-bottom-left-radius: 2px;
}
.dropdown-option:hover {
  background-color: #f4f4f4;
  color: #333;
}
.dropDown-options-checkbox span {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  box-sizing: border-box;
  display: block;
}
.dropdown-option.disabled {
  cursor: not-allowed;
}
.dropdown-option.disabled span {
  color: #ccc;
}
.dropdown-option.disabled:hover {
  color: #ccc;
  background-color: #f4f4f4;
}
.dropdown-option.is-selected {
  background-color: #f4f4f4;
  color: #333;
}
.dropdown-noresults {
  box-sizing: border-box;
  color: #ccc;
  cursor: default;
  display: block;
  padding: 8px 10px;
}

/* CSS for Accordion Component (based on Spectre.css) */
.accordion {
  margin-bottom: 16px;
  width: 100%;
}
.accordion .accordion-item {
  margin-bottom: 16px;
}
.accordion .accordion-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 42px;
  padding: 0 8px;
  background-color: #f7f7f7;
}
.accordion .accordion-header:hover {
  background-color: #f3f3f3;
  cursor: pointer;
}
.accordion .accordion-header h3 {
  font-size: 13px;
  font-weight: 500;
  color: #333333;
  padding-left: 12px;
  margin: 0;
}
.accordion .accordion-header .accordion-action .btn {
  min-width: auto;
  background: none;
  padding: 0 8px;
}
.accordion .accordion-header .accordion-action .btn:focus {
  outline: 0;
  box-shadow: none;
}
.accordion .accordion-header .accordion-action .btn:hover {
  opacity: 0.8;
}
.accordion .accordion-body {
  padding: 0 8px;
}
.accordion-title {
  border-width: 0px;
  margin: 10px;
}

