.inforiver-charts-root-wrapper .element-selector-wrapper {
  background-color: #f5f5f5;
  display: flex;
  width: 100%;
  height: 100%;
  justify-content: center;
  align-items: center;
  flex-direction: column;
  gap: 5px;
  padding: 5px;
  color: #212121;
}
.inforiver-charts-root-wrapper .element-selector-wrapper .element-selector-title {
  color: #666;
  font-size: 12px;
}
.inforiver-charts-root-wrapper .element-selector-wrapper .element-selector-icons-wrapper {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
}
.inforiver-charts-root-wrapper .element-selector-wrapper .element-selector-icons-wrapper .icon-label {
  border: 1px solid #dddddd;
  background-color: #fff;
  width: 25px;
  height: 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.inforiver-charts-root-wrapper .wizard-navigation-container {
  border-bottom: 1px solid #dddddd;
  margin-bottom: 10px;
  padding-bottom: 10px;
  justify-content: space-between;
  overflow: hidden;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper {
  display: flex;
  align-items: center;
  margin-right: 8px;
  cursor: default;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .title-text {
  font-size: 12px;
  font-weight: 400;
  color: #444444;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .title-arrow {
  width: 177px;
  position: relative;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .title-arrow::before {
  content: '';
  position: absolute;
  left: 10px;
  top: 0;
  width: 100%;
  border: 1px dashed #666666;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .title-arrow::after {
  content: '\F090';
  font-family: 'FabricMDL2Icons';
  position: absolute;
  right: -16px;
  transform: rotate(90deg);
  top: -5px;
  font-size: 12px;
  color: #666666;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .badge {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background-color: #666666;
  color: #ffffff;
  font-size: 10px;
  text-align: center;
  line-height: 17px;
  margin-right: 6px;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper .badge .ms-Icon {
  font-size: 10px;
  font-weight: bold;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper.active .badge {
  background-color: #0078d4;
}
.inforiver-charts-root-wrapper .wizard-navigation-container .title-wrapper.active .title-text {
  font-weight: 600;
}
.inforiver-charts-root-wrapper .wizard-customize-container {
  height: 285px;
  overflow-y: auto;
  overflow-x: hidden;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container {
  padding-right: 10px;
  min-width: 310px;
  width: 50%;
  gap: 10px;
  border-right: 1px solid #dddddd;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list {
  width: 100%;
  display: grid;
  align-items: center;
  grid-template-columns: 40% 1fr;
  gap: 5px;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list .item-label {
  font-size: 12px;
  color: #333333;
  font-weight: 600;
  padding: 0;
  width: auto;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list .item-sub-label {
  font-size: 12px;
  color: #333333;
  font-weight: 400;
  padding-left: 16px;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list .item-sub-label.item-error-label {
  display: flex;
  gap: 5px;
  align-items: center;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list .item-container {
  display: flex;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .wizard-list .item-container.horizontal-custom-radio {
  min-height: 24px;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .tab-component-container,
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .side-panel-body {
  padding: 0 !important;
}
.inforiver-charts-root-wrapper .wizard-customize-container .right-container {
  width: 100%;
  padding-left: 10px;
}
.inforiver-charts-root-wrapper .wizard-customize-container .right-container .wizard-grid-menus {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 10px;
  height: 100%;
  overflow-y: auto;
}
.inforiver-charts-root-wrapper .wizard-customize-container .right-container .element_container {
  border: none;
  box-shadow: none;
  overflow: inherit;
}
.inforiver-charts-root-wrapper .wizard-customize-container .right-container .element_container .element_list {
  padding: 6px 0;
}
.inforiver-charts-root-wrapper .wizard-customize-container .right-container .element_container .element_list .element_label {
  font-weight: 600;
  color: #333333;
  margin-right: 20px;
}
.inforiver-charts-root-wrapper .wizard-customize-container .left-container .section-title,
.inforiver-charts-root-wrapper .wizard-customize-container .right-container .section-title {
  font-size: 14px;
  color: #333333;
  font-weight: 300;
}
.inforiver-charts-root-wrapper .wizard-customize-container .side-panel-wrapper {
  height: inherit;
  overflow: inherit;
}
.inforiver-charts-root-wrapper .wizard-customize-container .info-text {
  font-size: 14px;
  font-style: italic;
  color: #666;
}
.inforiver-charts-root-wrapper .wizard-customize-container .info-text.info-recommended-text {
  white-space: nowrap;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .advanced-tab-content.ranking {
  overflow: auto;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .left-container {
  min-width: 280px;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .matrix-sorting-controls-body {
  max-height: 140px;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .rank-container-matrix-content-wrapper {
  max-height: inherit;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .wizard-list {
  display: flex;
  justify-content: space-between;
  height: 32px;
}
.inforiver-charts-root-wrapper .wizard-customize-container.advanced .wizard-list .item-sub-label {
  font-weight: 600;
}
.inforiver-charts-root-wrapper .wizard-customize-container.customize .left-container {
  padding-right: 0;
  border-right: none;
}
.inforiver-charts-root-wrapper .wizard-customize-container.customize .side-panel-wrapper.chartWizardWrapper {
  padding-right: 10px;
  border-right: 1px solid #dddddd;
}
.inforiver-charts-root-wrapper .wizard-customize-container.customize .side-panel-wrapper.chartWizardWrapper .side-panel-body-wrapper {
  min-height: 285px;
}
.inforiver-charts-root-wrapper .wizard-footer {
  border-top: 1px solid #dddddd;
  margin-top: 10px;
  padding-top: 10px;
}
.inforiver-charts-root-wrapper .wizard-footer .side-panel-footer {
  padding: 0;
}
.inforiver-charts-root-wrapper .wizard-footer .action-button {
  padding: 9px 12px;
}
.inforiver-charts-root-wrapper .wizard-footer .data-info {
  display: flex;
  align-items: center;
  background-color: #fff4ce;
  font-size: 12px;
  color: #201f1e;
  padding: 8px 12px;
  border-radius: 4px;
  height: 32px;
  gap: 8px;
}
.inforiver-charts-root-wrapper .wizard-footer .data-info .ms-Icon {
  font-size: 16px;
  color: #ffb200;
}
.inforiver-charts-root-wrapper .scenario-wrapper .chart-fav-icon {
  opacity: 0;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  font-size: 10px;
  text-align: center;
  line-height: 13px;
  position: absolute;
  top: 3px;
  right: 3px;
  background-color: #ffffff;
  box-shadow: 1px 1px 4px 0px #0000002e;
}
.inforiver-charts-root-wrapper .scenario-wrapper .chart-fav-icon .ms-Icon {
  font-size: 10px;
}
.inforiver-charts-root-wrapper .scenario-wrapper .chart-fav-icon.active {
  color: #0078d4;
}
.inforiver-charts-root-wrapper .scenario-wrapper:hover .chart-fav-icon {
  opacity: 1;
}
.inforiver-charts-root-wrapper .scenario-charts {
  display: inline-block;
